import{_ as a,c as s,ag as e,o as r}from"./chunks/framework.-a8jReyC.js";const g=JSON.parse('{"title":"Solução de Problemas","description":"","frontmatter":{"title":"Solução de Problemas"},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),t={name:"troubleshooting.md"};function l(i,o,n,u,m,d){return r(),s("div",null,o[0]||(o[0]=[e('<h1 id="solucao-de-problemas" tabindex="-1">Solução de Problemas <a class="header-anchor" href="#solucao-de-problemas" aria-label="Permalink to &quot;Solução de Problemas&quot;">​</a></h1><details class="details custom-block"><summary>Problema: Não consigo importar minha fatura</summary><ul><li><strong>Causa:</strong> Arquivo em formato não suportado ou nenhuma transação reconhecida.</li><li><strong>Solução:</strong> Confirme que o arquivo é <strong>PDF</strong> ou <strong>OFX</strong> e que é a fatura do cartão. Se aparecer &quot;Nenhuma transação encontrada&quot;, o arquivo pode estar protegido por senha ou em outro formato — baixe novamente no app do banco.</li></ul></details><details class="details custom-block"><summary>Problema: Importação aponta duplicatas que não são duplicatas</summary><ul><li><strong>Causa:</strong> Descrições, valores ou datas semelhantes entre compras diferentes.</li><li><strong>Solução:</strong> Revise a lista de duplicatas e <strong>desmarque</strong> as que deseja importar de verdade. Você também pode editar a descrição/valor/data antes de confirmar.</li></ul></details><details class="details custom-block"><summary>Problema: Atingi o limite de transações do mês</summary><ul><li><strong>Causa:</strong> O plano gratuito (Controle Inicial) permite até 100 transações por mês.</li><li><strong>Solução:</strong> Aguarde o reset no início do próximo mês ou <strong>atualize para o plano Essencial</strong> para transações ilimitadas.</li></ul></details><details class="details custom-block"><summary>Problema: Atingi o limite de importações do mês</summary><ul><li><strong>Causa:</strong> O plano gratuito permite 1 importação de fatura por mês.</li><li><strong>Solução:</strong> No plano Essencial ou Equilíbrio Total a importação é ilimitada. Você pode atualizar seu plano no Perfil.</li></ul></details><details class="details custom-block"><summary>Problema: Não consigo criar mais categorias</summary><ul><li><strong>Causa:</strong> Você pode ter atingido o limite do plano gratuito (10 categorias).</li><li><strong>Solução:</strong> Atualize para o plano Essencial ou Equilíbrio Total para categorias ilimitadas.</li></ul></details><details class="details custom-block"><summary>Problema: Não consigo acessar minha conta</summary><ul><li><strong>Causa:</strong> Conta bloqueada por segurança ou sessão expirada.</li><li><strong>Solução:</strong> Entre com sua conta Google novamente. Se o problema persistir, entre em contato com o suporte em <a href="mailto:support@flyca.sh" target="_blank" rel="noreferrer">support@flyca.sh</a>.</li></ul></details><details class="details custom-block"><summary>Problema: Não consigo criar transações recorrentes</summary><ul><li><strong>Causa:</strong> Configuração incorreta do período de recorrência ou erro no sistema.</li><li><strong>Solução:</strong> Certifique-se de que todos os campos estão preenchidos corretamente. Se o erro continuar, atualize para a última versão.</li></ul></details><details class="details custom-block"><summary>Problema: A visualização de saldos está incorreta</summary><ul><li><strong>Causa:</strong> Grupos ou categorias utilizados no cálculo podem ter sido excluídos.</li><li><strong>Solução:</strong> Revise os saldos criados e ajuste ou exclua aqueles que usam grupos ou categorias inexistentes.</li></ul></details><details class="details custom-block"><summary>Problema: O gráfico do Fluxo de Caixa não mostra meus dados</summary><ul><li><strong>Causa:</strong> O ano selecionado pode não ter transações, ou as transações estão com data de pagamento diferente da esperada.</li><li><strong>Solução:</strong> Verifique o ano selecionado e o modo de data (compra ou pagamento). Atualize os dados com o botão &quot;Atualizar&quot;.</li></ul></details><details class="details custom-block"><summary>Problema: A análise por categoria está bloqueada</summary><ul><li><strong>Causa:</strong> A análise por categoria completa (totais e principais transações) exige o plano Essencial; os relatórios avançados (variação, comparativo, insights) e a exportação XLSX exigem o Equilíbrio Total.</li><li><strong>Solução:</strong> Atualize seu plano no Perfil para desbloquear os relatórios.</li></ul></details><details class="details custom-block"><summary>Problema: A tabela de categorias não carrega</summary><ul><li><strong>Causa:</strong> Cache do navegador corrompido ou erro no sistema.</li><li><strong>Solução:</strong> Limpe o cache do navegador e reinicie o aplicativo. Caso não resolva, atualize para a versão mais recente.</li></ul></details><details class="details custom-block"><summary>Problema: O aplicativo está lento</summary><ul><li><strong>Causa:</strong> Muitos dados armazenados ou dispositivo com pouca memória disponível.</li><li><strong>Solução:</strong> Exclua transações antigas para reduzir o volume no aplicativo. Verifique o desempenho do dispositivo.</li></ul></details>',13)]))}const p=a(t,[["render",l]]);export{g as __pageData,p as default};
